def ternary_digit(n, k):
    """Get k-th ternary digit of n (0 = least significant)."""
    return (n // (3**k)) % 3

def check_c30_lead(r):
    """
    Check whether {r * log3(2)} is in C30Lead.
    Returns True if it IS in C30Lead (i.e. floor(3^({r*alpha}+29)) has no digit 2).
    Returns False if it is NOT in C30Lead (i.e. has digit 2 somewhere).
    """
    alpha = log3_2
    ra = Decimal(r) * alpha
    frac = ra - int(ra)  # {r*alpha}
    
    # Compute 3^(frac + 29)
    val = Decimal(3) ** (frac + 29)
    block = int(val)
    
    # Check if block has digit 2 in base 3 (in positions 0..29)
    for k in range(30):
        if ternary_digit(block, k) == 2:
            return False  # Has digit 2 -> NOT in C30Lead
    return True  # No digit 2 -> IS in C30Lead

# Verify all N_12 elements
